function initMail(){fetch("/api/email").then(e=>e.json()).then(({email:e})=>{const n=document.getElementById("mailBtn");n&&n.addEventListener("click",n=>{n.preventDefault(),window.location.href=`mailto:${e}`});document.querySelectorAll("#email").forEach(n=>{n.innerHTML=`<a href="mailto:${e}" class="email-link">${e}</a>`})}).catch(e=>{console.error("\u274c Error al obtener el correo desde el backend:",e)})}export{initMail};